using System.Data;
using attendence.Models;
using Microsoft.Data.SqlClient;
namespace attendence.Data;
public sealed class AttendanceReportRepository(DbConnectionFactory connections)
{
    public async Task<IReadOnlyList<AttendanceReportRow>> GetAsync(AttendanceReportViewModel f,CancellationToken ct,int? teacherId=null)
    {
        var rows=new List<AttendanceReportRow>();await using var c=connections.CreateConnection();await using var q=c.CreateCommand();
        q.CommandText="""SELECT ses.SessionDate,COALESCE(ses.Period,N'') AS Period,cl.Name,sub.Name,stu.EnrollmentNumber,stu.FullName,ar.Status,ar.Remarks FROM dbo.AttendanceRecords ar JOIN dbo.AttendanceSessions ses ON ses.SessionId=ar.SessionId JOIN dbo.Students stu ON stu.StudentId=ar.StudentId JOIN dbo.Subjects sub ON sub.SubjectId=ses.SubjectId JOIN dbo.Classes cl ON cl.ClassId=sub.ClassId WHERE (@ClassId IS NULL OR cl.ClassId=@ClassId) AND (@SubjectId IS NULL OR sub.SubjectId=@SubjectId) AND (@StudentId IS NULL OR stu.StudentId=@StudentId) AND (@Start IS NULL OR ses.SessionDate>=@Start) AND (@End IS NULL OR ses.SessionDate<=@End) AND (@Status IS NULL OR ar.Status=@Status) AND (@TeacherId IS NULL OR EXISTS(SELECT 1 FROM dbo.TeacherAssignments ta JOIN dbo.Teachers t ON t.TeacherId=ta.TeacherId AND t.IsActive=1 WHERE ta.TeacherId=@TeacherId AND ta.SubjectId=sub.SubjectId)) ORDER BY ses.SessionDate DESC,cl.Name,sub.Name,stu.FullName;""";
        q.Parameters.Add("@ClassId",SqlDbType.Int).Value=(object?)f.ClassId??DBNull.Value;q.Parameters.Add("@SubjectId",SqlDbType.Int).Value=(object?)f.SubjectId??DBNull.Value;q.Parameters.Add("@StudentId",SqlDbType.Int).Value=(object?)f.StudentId??DBNull.Value;
        q.Parameters.Add("@Start",SqlDbType.Date).Value=(object?)f.StartDate?.Date??DBNull.Value;q.Parameters.Add("@End",SqlDbType.Date).Value=(object?)f.EndDate?.Date??DBNull.Value;q.Parameters.Add("@Status",SqlDbType.NVarChar,10).Value=string.IsNullOrWhiteSpace(f.Status)?DBNull.Value:f.Status;q.Parameters.Add("@TeacherId",SqlDbType.Int).Value=(object?)teacherId??DBNull.Value;
        await c.OpenAsync(ct);await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))rows.Add(new(){Date=r.GetDateTime(0),Period=r.GetString(1),ClassName=r.GetString(2),Subject=r.GetString(3),EnrollmentNumber=r.GetString(4),StudentName=r.GetString(5),Status=r.GetString(6),Remarks=r.IsDBNull(7)?null:r.GetString(7)});return rows;
    }
    public async Task<IReadOnlyList<(int Id,string Name)>> StudentsAsync(CancellationToken ct,int? teacherId=null)
    {var rows=new List<(int,string)>();await using var c=connections.CreateConnection();await using var q=c.CreateCommand();q.CommandText="SELECT DISTINCT s.StudentId,s.EnrollmentNumber+N' · '+s.FullName FROM dbo.Students s WHERE s.IsActive=1 AND (@TeacherId IS NULL OR EXISTS(SELECT 1 FROM dbo.TeacherAssignments ta JOIN dbo.Subjects sub ON sub.SubjectId=ta.SubjectId JOIN dbo.Teachers t ON t.TeacherId=ta.TeacherId AND t.IsActive=1 WHERE ta.TeacherId=@TeacherId AND sub.ClassId=s.ClassId)) ORDER BY s.EnrollmentNumber+N' · '+s.FullName;";q.Parameters.Add("@TeacherId",SqlDbType.Int).Value=(object?)teacherId??DBNull.Value;await c.OpenAsync(ct);await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))rows.Add((r.GetInt32(0),r.GetString(1)));return rows;}
    public async Task<StudentPortalViewModel?> GetStudentPortalAsync(int studentId,CancellationToken ct)
    {
        var model=new StudentPortalViewModel();await using var c=connections.CreateConnection();await c.OpenAsync(ct);
        await using(var q=c.CreateCommand()){q.CommandText="SELECT s.FullName,s.EnrollmentNumber,COUNT(CASE WHEN ar.Status='Present' THEN 1 END),COUNT(CASE WHEN ar.Status='Absent' THEN 1 END),COUNT(CASE WHEN ar.Status='Late' THEN 1 END),COUNT(CASE WHEN ar.Status='Excused' THEN 1 END),COALESCE(100.0*COUNT(CASE WHEN ar.Status IN('Present','Late') THEN 1 END)/NULLIF(COUNT(CASE WHEN ar.Status IN('Present','Absent','Late') THEN 1 END),0),0) FROM dbo.Students s LEFT JOIN dbo.AttendanceRecords ar ON ar.StudentId=s.StudentId WHERE s.StudentId=@StudentId AND s.IsActive=1 GROUP BY s.StudentId,s.FullName,s.EnrollmentNumber;";q.Parameters.Add("@StudentId",SqlDbType.Int).Value=studentId;await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))return null;model.StudentName=r.GetString(0);model.EnrollmentNumber=r.GetString(1);model.Present=r.GetInt32(2);model.Absent=r.GetInt32(3);model.Late=r.GetInt32(4);model.Excused=r.GetInt32(5);model.AttendancePercentage=r.GetDouble(6);}
        await using(var q=c.CreateCommand()){q.CommandText="SELECT ses.SessionDate,COALESCE(ses.Period,N''),cl.Name,sub.Name,stu.EnrollmentNumber,stu.FullName,ar.Status,ar.Remarks FROM dbo.AttendanceRecords ar JOIN dbo.AttendanceSessions ses ON ses.SessionId=ar.SessionId JOIN dbo.Students stu ON stu.StudentId=ar.StudentId JOIN dbo.Subjects sub ON sub.SubjectId=ses.SubjectId JOIN dbo.Classes cl ON cl.ClassId=sub.ClassId WHERE stu.StudentId=@StudentId ORDER BY ses.SessionDate DESC,ses.SessionId DESC;";q.Parameters.Add("@StudentId",SqlDbType.Int).Value=studentId;await using var r=await q.ExecuteReaderAsync(ct);var rows=new List<AttendanceReportRow>();while(await r.ReadAsync(ct))rows.Add(new(){Date=r.GetDateTime(0),Period=r.GetString(1),ClassName=r.GetString(2),Subject=r.GetString(3),EnrollmentNumber=r.GetString(4),StudentName=r.GetString(5),Status=r.GetString(6),Remarks=r.IsDBNull(7)?null:r.GetString(7)});model.Records=rows;}
        return model;
    }
    public async Task<(double Threshold,IReadOnlyList<LowAttendanceRow> Students)> GetLowAttendanceAsync(CancellationToken ct,int? teacherId=null)
    {
        await using var c=connections.CreateConnection();await c.OpenAsync(ct);double threshold=75;await using(var q=c.CreateCommand()){q.CommandText="SELECT COALESCE(TRY_CONVERT(float,(SELECT [Value] FROM dbo.ApplicationSettings WHERE [Key]=N'LowAttendanceThreshold')),75.0);";threshold=Convert.ToDouble(await q.ExecuteScalarAsync(ct));}
        var rows=new List<LowAttendanceRow>();await using(var q=c.CreateCommand()){q.CommandText="""WITH Totals AS(SELECT s.StudentId,s.EnrollmentNumber,s.FullName,cl.Name AS ClassName,CAST(100.0*SUM(CASE WHEN ar.Status IN('Present','Late') THEN 1.0 ELSE 0 END)/NULLIF(COUNT(CASE WHEN ar.Status IN('Present','Absent','Late') THEN 1 END),0) AS float) AS Pct FROM dbo.Students s LEFT JOIN dbo.Classes cl ON cl.ClassId=s.ClassId JOIN dbo.AttendanceRecords ar ON ar.StudentId=s.StudentId WHERE s.IsActive=1 AND (@TeacherId IS NULL OR EXISTS(SELECT 1 FROM dbo.TeacherAssignments ta JOIN dbo.Teachers t ON t.TeacherId=ta.TeacherId AND t.IsActive=1 JOIN dbo.Subjects sub ON sub.SubjectId=ta.SubjectId WHERE ta.TeacherId=@TeacherId AND sub.ClassId=s.ClassId)) GROUP BY s.StudentId,s.EnrollmentNumber,s.FullName,cl.Name) SELECT EnrollmentNumber,FullName,ClassName,Pct FROM Totals WHERE Pct<@Threshold ORDER BY Pct,FullName;""";q.Parameters.Add("@Threshold",SqlDbType.Float).Value=threshold;q.Parameters.Add("@TeacherId",SqlDbType.Int).Value=(object?)teacherId??DBNull.Value;await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))rows.Add(new(r.GetString(0),r.GetString(1),r.IsDBNull(2)?null:r.GetString(2),Convert.ToDouble(r.GetDecimal(3))));}
        return(threshold,rows);
    }
}
